// UI-only caller transport. Screenshot paths are generated by the harness;
// callers cannot choose filesystem paths, URLs, selectors, or scripts.
import {join} from 'node:path';
import {randomUUID} from 'node:crypto';
import {readFile} from 'node:fs/promises';
import {validateBrowserArgs,isGesture} from './caller-workflow-agent.mjs';

export function callerUiBrowser({command,receiptsDirectory,readImage=readFile,now=Date.now}) {
  let viewport=null;
  return async args=>{
    validateBrowserArgs(args);
    if(args[0]==='screenshot'){
      if(!receiptsDirectory)throw Error('Screenshot receipt directory required');
      const file=`caller-${randomUUID()}.png`;
      await command(['screenshot',join(receiptsDirectory,file)]);
      const png=await readImage(join(receiptsDirectory,file));
      if(png.subarray(0,8).toString('hex')!=='89504e470d0a1a0a'||png.length<24)throw Error('Invalid screenshot receipt');
      viewport={file,width:png.readUInt32BE(16),height:png.readUInt32BE(20),at:now()};
      return {screenshot:{...viewport,basis:'current_browser_viewport',historical:true}};
    }
    if(args[0]==='click_at'){
      const observed=viewport;viewport=null;const x=Number(args[1]),y=Number(args[2]);
      if(!observed||now()-observed.at>30000||x>=observed.width||y>=observed.height)
        throw Error('Coordinate click requires a fresh viewport screenshot and in-bounds coordinates');
      await command(['mouse','move',String(x),String(y)]);
      try{await command(['mouse','down']);}finally{await command(['mouse','up']);}
      return {clicked:{x,y,screenshot:observed.file},verification:'Observe the result before assessing the effect'};
    }
    if(isGesture(args))viewport=null;
    if(args[0]==='find'){
      const observed=await command(['snapshot']);
      const labels=String(observed.snapshot??'').split('\n').flatMap(line=>{
        const match=line.trimStart().match(/^- StaticText ("(?:\\.|[^"\\])*")$/);
        if(!match)return [];try{return [JSON.parse(match[1])];}catch{return [];}
      });
      if(observed.limited||labels.filter(text=>text===args[2]).length!==1)
        throw Error('Exact-text click requires one current observed text occurrence');
    }
    return command(args);
  };
}
